/**
 * Generates PNG icons for TanNote PWA manifest.
 * Run once: node generate-icons.mjs
 * Requires: npm install -g canvas   OR  use the inline SVG approach below
 *
 * This script creates icons by writing raw PNG via a canvas-free SVG→PNG path.
 * It uses the built-in SVG font rendering if available, otherwise a solid color.
 */

// We'll write the SVGs directly and rely on Vite/browser to resolve them.
// The real icons are generated by the build-icons.mjs script below that uses sharp.
// For now we just output placeholder files so the manifest doesn't 404.

import { writeFileSync } from 'fs';
import { createCanvas } from 'canvas'; // optional dep

const sizes = [192, 512];
const colors = { bg: '#E24B4A', text: '#ffffff' };

for (const size of sizes) {
  const canvas = createCanvas(size, size);
  const ctx = canvas.getContext('2d');

  // Background
  ctx.fillStyle = colors.bg;
  roundRect(ctx, 0, 0, size, size, size * 0.22);
  ctx.fill();

  // Lightning bolt "T" letter
  ctx.fillStyle = colors.text;
  ctx.font = `bold ${Math.round(size * 0.52)}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('T', size / 2, size / 2 + size * 0.03);

  writeFileSync(`icon-${size}.png`, canvas.toBuffer('image/png'));
  writeFileSync(`icon-maskable-${size}.png`, canvas.toBuffer('image/png'));
  console.log(`✓ icon-${size}.png`);
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}
